1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.Set;
5	
6	import org.springframework.samples.petclinic.model.FiscalYear;
7	import org.springframework.samples.petclinic.model.Luhn;
8	
9	/**
10	 * Formats and reads an owner's member id — the single identifier that unifies what were once
11	 * the separate customer code and membership number. It is formatted as
12	 * {@code <REGION><FY><HASH8><CHK>} (e.g. {@code NSW261A2B3C4D5}):
13	 * <ul>
14	 * <li>{@code REGION} — the region code derived from the owner's postcode (see
15	 * {@link org.springframework.samples.petclinic.model.CityRegion});</li>
16	 * <li>{@code FY} — the two-digit {@link FiscalYear fiscal year} of the registration date;</li>
17	 * <li>{@code HASH8} — the first 8 upper-case hex characters of
18	 * {@code SHA-256(normalizedTelephone + lastName)}, the same hash used by the region-and-hash
19	 * identity;</li>
20	 * <li>{@code CHK} — a single {@link Luhn} check digit over the digits of
21	 * {@code <REGION><FY><HASH8>}.</li>
22	 * </ul>
23	 * The id is derived purely from the owner's own fields, so the same owner always yields the same
24	 * id without any sequence or coordination.
25	 */
26	public final class MemberId {
27	
28	    /** Number of hex characters kept from the telephone-and-name hash. */
29	    private static final int HASH_LENGTH = 8;
30	
31	    private MemberId() {
32	    }
33	
34	    /**
35	     * The member id for an owner in {@code region} registered on {@code registrationDate} whose
36	     * normalized telephone and last name are given.
37	     */
38	    public static String format(String region, LocalDate registrationDate,
39	            String normalizedTelephone, String lastName) {
40	        String telephone = normalizedTelephone == null ? "" : normalizedTelephone;
41	        String last = lastName == null ? "" : lastName;
42	        String fy = String.format("%02d", FiscalYear.of(registrationDate) % 100);
43	        String hash8 = Hashes.upperHexPrefix(telephone + last, HASH_LENGTH);
44	        String base = region + fy + hash8;
45	        return base + Luhn.checkDigit(base);
46	    }
47	
48	    /**
49	     * De-duplicates {@code memberId} against the ids already {@code taken}. Returns
50	     * {@code memberId} unchanged when it is free; otherwise appends {@code -<n>} with the
51	     * smallest {@code n} of 2 or more that yields an id not in {@code taken}
52	     * (e.g. {@code NSW261A2B3C4D5-2}).
53	     */
54	    public static String deduplicate(String memberId, Set<String> taken) {
55	        if (!taken.contains(memberId)) {
56	            return memberId;
57	        }
58	        for (int n = 2; ; n++) {
59	            String candidate = memberId + "-" + n;
60	            if (!taken.contains(candidate)) {
61	                return candidate;
62	            }
63	        }
64	    }
65	
66	    /**
67	     * The {@code REGION} segment of a member id — its leading run of letters, i.e. the region
68	     * the id was minted in. The fiscal-year segment that follows always begins with a digit, so
69	     * the region is exactly this leading alphabetic prefix.
70	     */
71	    public static String region(String memberId) {
72	        int end = 0;
73	        while (end < memberId.length() && Character.isLetter(memberId.charAt(end))) {
74	            end++;
75	        }
76	        return memberId.substring(0, end);
77	    }
78	}
