3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Stamps the new owner with its {@link Households#id(Owner) household id}, derived
8	 * deterministically from its last name and postcode. Owners sharing a last name and postcode
9	 * receive the same id automatically, so no existing owner needs updating and the link exists
10	 * without any {@code sharesHousehold} opt-in.
11	 */
12	public class AssignHousehold {
13	
14	    public void service(@Val Owner owner) {
15	        owner.setHouseholdId(Households.id(owner));
16	    }
17	}
