1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.CityRegion;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * Assigns a new owner's member id before it is saved. The id is {@code <REGION><FY><HASH8><CHK>}
13	 * (see {@link MemberId}): the region derived from the owner's postcode, the two-digit fiscal year
14	 * of the registration date, a hash of the owner's normalized telephone and last name, and a Luhn
15	 * check digit. Runs after the telephone has been normalized and the registration date rolled onto
16	 * a business day, so {@link Owner#getTelephone()} and {@link Owner#getRegistrationDate()} already
17	 * hold the canonical forms the id is built over. Should that id collide with an existing owner's,
18	 * it is de-duplicated with a {@code -<n>} suffix.
19	 */
20	public class AssignMemberId {
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
23	        String region = CityRegion.localityOf(owner.getPostcode(), owner.getCity());
24	        String memberId = MemberId.format(region, owner.getRegistrationDate(),
25	                owner.getTelephone(), owner.getLastName());
26	        Set<String> taken = new HashSet<>();
27	        for (Owner existing : ownerRepository.findAllActive()) {
28	            if (existing.getMemberId() != null) {
29	                taken.add(existing.getMemberId());
30	            }
31	        }
32	        owner.setMemberId(MemberId.deduplicate(memberId, taken));
33	    }
34	}
