115	    }
116	
117	    public String getAddressLine2() {
118	        return this.addressLine2;
119	    }
120	
121	    public void setAddressLine2(String addressLine2) {
122	        this.addressLine2 = addressLine2;
123	    }
124	
125	    public String getAddress() {
126	        return this.address;
127	    }
128	
129	    public void setAddress(String address) {
130	        this.address = address;
131	    }
132	
133	    public String getCity() {
134	        return this.city;
135	    }
136	
137	    public void setCity(String city) {
138	        this.city = city;
139	    }
140	
141	    public String getPostcode() {
142	        return this.postcode;
143	    }
144	
145	    public void setPostcode(String postcode) {
146	        this.postcode = postcode;
147	    }
148	
149	    public String getTelephone() {
150	        return this.telephone;
151	    }
152	
153	    public void setTelephone(String telephone) {
154	        this.telephone = telephone;
155	    }
156	
157	    public String getEmail() {
158	        return this.email;
159	    }
160	
161	    public void setEmail(String email) {
162	        this.email = email;
163	    }
164	
165	    /** Whether this owner has a non-blank email address. */
166	    public boolean hasEmail() {
167	        return this.email != null && !this.email.isBlank();
168	    }
169	
170	    public LocalDate getRegistrationDate() {
171	        return this.registrationDate;
172	    }
173	
174	    public void setRegistrationDate(LocalDate registrationDate) {
175	        this.registrationDate = registrationDate;
176	    }
177	
178	    public LocalDate getBirthDate() {
179	        return this.birthDate;
180	    }
181	
182	    public void setBirthDate(LocalDate birthDate) {
183	        this.birthDate = birthDate;
184	    }
185	
186	    public String getMemberId() {
187	        return this.memberId;
188	    }
189	
190	    public void setMemberId(String memberId) {
191	        this.memberId = memberId;
192	    }
193	
194	    /**
195	     * The owner's primary identifier — the {@link #getMemberId() member id}. This is the single
196	     * point that decides which field identifies an owner, so every caller (such as the
197	     * created-owner audit event) follows it without further change.
198	     */
199	    public String getPrimaryIdentifier() {
200	        return getMemberId();
201	    }
202	
203	    public String getHouseholdId() {
204	        return this.householdId;
