224	        this.householdMemberCount = householdMemberCount;
225	    }
226	
227	    /**
228	     * The ceiling on this owner's membership level, fixed at creation as one above the
229	     * highest membership level then present among their household members (see
230	     * {@link org.springframework.samples.petclinic.rest.function.owner.CapMembershipLevel}).
231	     * {@code null} when the owner had no existing household member, in which case no cap
232	     * applies.
233	     */
234	    public Integer getMembershipLevelCap() {
235	        return this.membershipLevelCap;
236	    }
237	
238	    public void setMembershipLevelCap(Integer membershipLevelCap) {
239	        this.membershipLevelCap = membershipLevelCap;
240	    }
241	
242	    public Boolean getPossibleDuplicate() {
243	        return this.possibleDuplicate;
244	    }
245	
246	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
247	        this.possibleDuplicate = possibleDuplicate;
248	    }
249	
250	    public Integer getPossibleDuplicateOf() {
251	        return this.possibleDuplicateOf;
252	    }
253	
254	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
255	        this.possibleDuplicateOf = possibleDuplicateOf;
256	    }
257	
258	    /** Whether this owner has been soft-deleted: the row is retained but hidden from
259	     * duplicate and identity checks (see {@link #setDeleted}). */
260	    public boolean isDeleted() {
