3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.springframework.stereotype.Component;
6	
7	/**
8	 * Hands out monotonically increasing sequence numbers for audit events, so each emitted
9	 * event carries a strictly ordered {@code seq} across every create. Thread-safe and
10	 * application-scoped; the first number handed out is 1.
11	 */
12	@Component
13	public class AuditSequence {
14	
15	    private final AtomicLong counter = new AtomicLong();
16	
17	    /** The next sequence number, one greater than the previous. */
18	    public long next() {
19	        return this.counter.incrementAndGet();
20	    }
21	}
