19	     * lives in a city over its soft capacity. */
20	    static boolean of(Owner owner, OwnerRepository ownerRepository) {
21	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
22	                || (owner.hasEmail() && Emails.isDisposableAdjacent(owner.getEmail()))
23	                || Cities.isOverSoftCapacity(ownerRepository, owner.getCity());
