3	import java.util.Objects;
4	import java.util.Optional;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Soft duplicate matching: a new owner is a <em>possible</em> duplicate of an existing owner
11	 * when their last names sound alike (same {@link Soundex#encode Soundex}) and they share a
12	 * postcode, yet their {@link IdentityKeys identity keys} differ — typically because the
13	 * telephone (part of the key) differs.
14	 *
15	 * <p>Unlike a duplicate identity (see {@link EnsureUniqueIdentity}), which is rejected outright
16	 * as a re-registration, a possible duplicate is still created and merely flagged with the id of
17	 * the owner it resembles. The differing identity key is what distinguishes it from an exact
18	 * re-registration.
19	 */
20	final class PossibleDuplicates {
21	
22	    private PossibleDuplicates() {
23	    }
24	
25	    /**
26	     * The id of the earliest existing owner the given owner possibly duplicates — matching
27	     * last-name Soundex and postcode but a different identity key — or empty when there is no
28	     * such owner.
29	     */
30	    static Optional<Integer> matchFor(Owner owner, OwnerRepository ownerRepository) {
31	        Owner match = null;
32	        for (Owner existing : ownerRepository.findAllActive()) {
33	            if (matches(owner, existing) && (match == null || existing.getId() < match.getId())) {
34	                match = existing;
35	            }
36	        }
37	        return Optional.ofNullable(match).map(Owner::getId);
38	    }
39	
40	    private static boolean matches(Owner owner, Owner existing) {
41	        return Soundex.encode(owner.getLastName()).equals(Soundex.encode(existing.getLastName()))
42	                && Objects.equals(owner.getPostcode(), existing.getPostcode())
43	                && !IdentityKeys.of(owner).equals(IdentityKeys.of(existing));
44	    }
45	}
