1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * The American Soundex phonetic encoding of a name: a letter followed by three digits that
5	 * collapses similar-sounding surnames onto the same code. Used to key identity and soft
6	 * duplicate matching on how a last name <em>sounds</em> rather than on its exact spelling, so
7	 * that spelling variants of one surname share a code.
8	 */
9	final class Soundex {
10	
11	    private Soundex() {
12	    }
13	
14	    /**
15	     * The four-character Soundex code of {@code name} (first letter, then three digits, zero
16	     * padded). Non-letters are ignored; {@code h} and {@code w} are transparent (they do not
17	     * separate two consonants sharing a code) while vowels and {@code y} do separate them.
18	     * Returns an empty string when {@code name} holds no letters.
19	     */
20	    static String encode(String name) {
21	        if (name == null) {
22	            return "";
23	        }
24	        StringBuilder letters = new StringBuilder();
25	        for (int i = 0; i < name.length(); i++) {
26	            char c = name.charAt(i);
27	            if (Character.isLetter(c)) {
28	                letters.append(Character.toUpperCase(c));
29	            }
30	        }
31	        if (letters.length() == 0) {
32	            return "";
33	        }
34	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
35	        char previous = digitOf(letters.charAt(0));
36	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
37	            char c = letters.charAt(i);
38	            if (c == 'H' || c == 'W') {
39	                continue; // transparent: leave the previous code in place
40	            }
41	            char digit = digitOf(c);
42	            if (digit != '0' && digit != previous) {
43	                code.append(digit);
44	            }
45	            previous = digit;
46	        }
47	        while (code.length() < 4) {
48	            code.append('0');
49	        }
50	        return code.toString();
51	    }
52	
53	    /**
54	     * The Soundex digit for {@code letter}: {@code '1'}-{@code '6'} for a coded consonant,
55	     * {@code '0'} for a vowel or any letter (including {@code y}) that carries no code.
56	     */
57	    private static char digitOf(char letter) {
58	        switch (letter) {
59	        case 'B': case 'F': case 'P': case 'V':
60	            return '1';
61	        case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
62	            return '2';
63	        case 'D': case 'T':
64	            return '3';
65	        case 'L':
66	            return '4';
67	        case 'M': case 'N':
68	            return '5';
69	        case 'R':
70	            return '6';
71	        default:
72	            return '0';
73	        }
74	    }
75	}
